input.command:
node -e "
let score = 250;
const base = 1100;
const inc = 100;
const every = 3;
const points = [score];
for (let i = 1; i <= 9; i++) {
  const interval = base + Math.floor((i - 1) / every) * inc;
  score += interval;
  points.push(score);
}
console.log(points.join(', '));
"
